SELECT id, sku_id, lot_id, location_id, quality_code, on_hand_qty, reserved_qty, version
FROM stock_balance
WHERE enterprise_id = #{enterpriseId} AND warehouse_id = #{warehouseId} AND id = #{balanceId}

SELECT id, operation_id, entry_no, balance_id, on_hand_delta, reserved_delta, free_execution_claim_delta,
       on_hand_after, reserved_after, free_execution_claim_after, balance_version, reason_code, document_id,
       actor_id, occurred_at
FROM stock_ledger
WHERE enterprise_id = #{enterpriseId}
  AND warehouse_id = #{warehouseId}
  AND balance_id = #{balanceId}

    AND id > #{cursor}

ORDER BY id
LIMIT #{limit}

SELECT id, warehouse_id, operation_id, entry_no, balance_id, on_hand_delta, reserved_delta,
       free_execution_claim_delta, on_hand_after, reserved_after, reason_code, document_id, occurred_at
FROM stock_ledger
WHERE enterprise_id = #{enterpriseId}
  AND operation_id = #{operationId}

    AND warehouse_id IN

        #{warehouseId}



    AND 1 = 0

ORDER BY warehouse_id, entry_no, id

SELECT id, action, fact_type, fact_parent_id, fact_part_id, fact_line_id, business_effect_key,
       active_command_id, applied_command_id, attempt_no, state, version
FROM stock_effect
WHERE enterprise_id = #{enterpriseId}
  AND warehouse_id = #{warehouseId}

    AND fact_parent_id = #{taskId}


    AND id > #{cursor}

ORDER BY id
LIMIT #{limit}
